<?php require __DIR__.'/includes/bootstrap.php';$number=trim((string)($_GET['order']??''));$order=shop_find_order($number);if(!$order){http_response_code(404);} ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order confirmation | TraveL Den Shop</title><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="/shop/assets/css/shop.css"></head><body><?php require __DIR__.'/includes/header.php'; ?><?php if(!$order):?><section class="order-confirmation"><h1>Order not found</h1><p>This confirmation is no longer available or does not belong to this browser session.</p><a class="shop-button" href="/shop/products.php">Return to shop</a></section><?php else:?><section class="order-confirmation"><h1>Order received</h1><p><strong>Order number:</strong> <?= shop_e($order['order_number']) ?></p><p><strong>Customer:</strong> <?= shop_e($order['customer']['full_name']) ?></p><p><strong>Delivery method:</strong> <?= shop_e($config['delivery'][$order['delivery_method']]['label']) ?></p><h2>Items</h2><ul><?php foreach($order['items'] as $item):?><li><?= (int)$item['quantity'] ?> × <?= shop_e($item['product']['name']) ?> — <?= shop_money($item['line_total']) ?></li><?php endforeach;?></ul><p><strong>Subtotal:</strong> <?= shop_money($order['subtotal']) ?> KES</p><p><strong>Delivery fee:</strong> <?= shop_money($order['delivery_fee']) ?> KES</p><p><strong>Total:</strong> <?= shop_money($order['total']) ?> KES</p><p><strong>Payment status:</strong> Pending</p><div class="notice"><strong>Payment pending.</strong> No payment has been confirmed. This shop does not falsely mark orders as paid. A secure payment gateway will be connected later; until then, staff must confirm payment through approved channels.</div></section><?php endif;?><?php require __DIR__.'/includes/footer.php'; ?></body></html>
